package br.edu.insper.transacoes;
import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import java.util.List; import java.util.Map;
@RestController @RequestMapping("/transactions") public class TransactionController { private final TransactionService service; public TransactionController(TransactionService service){this.service=service;} @GetMapping public List<TransactionResponse> list(@RequestParam(required=false) Long clientId){return service.list(clientId);}@PostMapping @ResponseStatus(HttpStatus.CREATED) public TransactionResponse create(@Valid @RequestBody CreateTransactionRequest r){return service.create(r);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){service.delete(id);}@ExceptionHandler({TransactionService.ClientMissing.class,TransactionService.TransactionMissing.class}) @ResponseStatus(HttpStatus.NOT_FOUND) Map<String,String> missing(){return Map.of("error","Recurso não encontrado");}}
